window.NPC_CHUNK_61 = [{"name":"Powderpot","cr":8,"xp":4800,"race":"charau-ka","gender":"Male","age_category":"Adult","classes":[{"class":"alchemist","level":7}],"alignment":"CE","size":"Small","type":"humanoid","sub_types":["charau-ka"],"init":5,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":22,"ac_touch":16,"ac_flat_footed":17,"ac_mods":"+5 Dex, +2 natural, +4 shield, +1 size","hp":102,"hd":"3d8+7d8+58","hd_value":10,"fort":11,"ref":15,"will":7,"save_mods":"+1 vs. fear, +4 vs. poison","speed":[{"type":"climb","speed":30},{"type":"land","speed":30}],"melee":"bite +16 (1d6+5), 2 claws +16 (1d4+5) or +1 boarding pike +17 (1d6+8/x3), bite +11 (1d6+2)","ranged":"bomb +19 (4d6+2 fire/19-20)","space":"5 ft.","reach":"5 ft. (10 ft. with boarding pike)","special_attacks":[{"type":"bomb","details":"11/day, 4d6+2 fire and catch fire, DC 15, 10-ft. radius"},{"type":"shrieking frenzy"},{"type":"thrown-weapon mastery"}],"extractsprepared_caster":"alchemist","extractsprepared_caster_level":7,"extractsprepared":[{"spell_level":3,"spells":[{"spell":"gaseous form"}]},{"spell_level":2,"spells":[{"spell":"aid"},{"spell":"blur"},{"spell":"bull's strength"},{"spell":"fire breath","used":true}]},{"spell_level":1,"spells":[{"spell":"bomber's eye","used":true},{"spell":"cure light wounds"},{"spell":"enlarge person"},{"spell":"shield"},{"spell":"touch of the sea","used":true}]}],"strength":21,"dexterity":20,"constitution":16,"intelligence":14,"wisdom":10,"charisma":8,"baseatk":7,"cmb":11,"cmd":26,"feats":[{"feat":"Brew Potion"},{"feat":"Extra Bombs*"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Throw Anything"},{"feat":"Toughness"},{"feat":"Weapon Focus (bomb)"}],"skills":[{"skill":"Climb","value":25},{"skill":"Craft (alchemy)","value":17},{"skill":"Intimidate","value":13},{"skill":"Perception","value":15},{"skill":"Profession (sailor)","value":10},{"skill":"Spellcraft","value":11},{"skill":"Stealth","value":18},{"skill":"Survival","value":10}],"languages":["Common","Abyssal","Osiriani","Polyglot"],"sq":["alchemy (alchemy crafting +7, identify potions)","discoveries (explosive bomb, feral mutagen, precise bombs [2 squares])","mutagen (+4/-2, +2 natural, 70 minutes)","poison use","swift alchemy","swift poisoning"],"special_abilities":[{"type":"Shrieking Frenzy","kind":"Su","details":"Once per day, a charau-ka can enter a state of shrieking frenzy as a free action. While in this state, the charau-ka automatically fails Stealth checks and cannot speak or cast spells that use verbal components (or use items that require command words to activate), but functions as if under the effects of a haste spell. The charau-ka can continue shrieking for up to 3 rounds, after which it is staggered for 1 round."},{"type":"Thrown-Weapon Mastery","kind":"Ex","details":"Charau-ka are masters of thrown weapons. All charau-ka gain Throw Anything as a bonus feat. In addition, charau-ka gain a +1 racial bonus on all thrown weapons, and their threat range for thrown weapons is doubled, as if they possessed the Improved Critical feat for all thrown weapons. This effect doesn't stack with any other effect that expands the threat range of a weapon."}],"gear":"+1 boarding pike, handy haversack, alchemist's kit, bandanna, formula book (contains all prepared formulae), tindertwigs (7), 60 gp, acid (3), alchemist's fire (3), liquid ice* (3), mutagen (Dex), tanglefoot bag, thunderstone (3)","before_combat":"When the alarm is sounded, Powderpot drinks his feral mutagen and extracts of aid, blur, bull's strength, and shield. In addition, his stat block includes the bonuses from the lord's banner of victory flying from the mainmast.","during_combat":"Powderpot throws explosive bombs at attackers, using his precise bombs discovery to avoid hitting the boatswain's mates. If attackers engage him in melee combat, Powderpot uses his boarding pike in an attempt to fend them off, but if anyone gets past his reach, he goes into a shrieking frenzy and attacks with his bite and claws. If he runs out of bombs, Powderpot drinks his extract of fire breath or hurls alchemical items such as alchemist's fire or liquid ice at foes.","morale":"Powderpot happily serves as the Filthy Lucre's mascot, but he is intelligent enough to recognize a losing battle when he's in one. If reduced to 20 hit points or fewer, he drinks his extract of gaseous form and attempts to retreat to safety.","base_statistics":"Without his mutagens and extracts and out of sight of the lord's banner, Powderpot's statistics are Init +3; AC 16, touch 14, flat-footed 13; hp 91; Fort +9, Ref +11, Will +6; Melee +1 boarding pike +12/+7 (1d6+5/x3), bite +6 (1d3+1); Ranged bomb +14 (4d6+2 fire/19-20); Str 17, Dex 16, Wis 12; CMB +9; CMD 22; Skills Climb +21, Craft (alchemy) +15, Intimidate +9, Perception +14, Profession (sailor) +9, Spellcraft +9, Stealth +14, Survival +9.","source":"AP 60, Pathfinder Campaign Setting: The Inner Sea World Guide 308, Pathfinder RPG Advanced Player's Guide 26"},{"name":"Druvalia Thrune","cr":13,"xp":25600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"aristocrat","level":1},{"class":"inquisitor of Thrune","level":13}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":11,"ac":28,"ac_touch":17,"ac_flat_footed":24,"ac_mods":"+9 armor, +3 deflection, +4 Dex, +2 shield","hp":117,"hd":"1d8+13d8+55","hd_value":14,"fort":15,"ref":13,"will":22,"defensive_abilities":["stalwart"],"dr":"5/good","speed":[{"type":"land","speed":30}],"melee":"+1 heavy mace +13 (1d8+2)","ranged":"crossbow of retribution +19 (1d10+5/17-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"greater bane","details":"13 rounds/day"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect alignment"}]},{"frequency":"13 rounds/day","spells":[{"spell":"discern lies"}]}],"spellsknown_caster":"inquisitor","spellsknown_caster_level":13,"spellsknown_concentration":14,"spellsknown":[{"spell_level":5,"spell_slots":2,"spells":[{"spell":"flame strike"},{"spell":"unwilling shield"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"defile armor"},{"spell":"divine power"},{"spell":"freedom of movement"},{"spell":"rebuke"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"dispel magic"},{"spell":"greater magic weapon"},{"spell":"heroism"},{"spell":"invisibility purge"},{"spell":"ward the faithful"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blistering invective"},{"spell":"flames of the faithful"},{"spell":"hold person"},{"spell":"silence"},{"spell":"weapon of awe"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command"},{"spell":"cure light wounds"},{"spell":"doom"},{"spell":"inflict light wounds"},{"spell":"true strike"},{"spell":"wrath"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"guidance"},{"spell":"light"},{"spell":"read magic"},{"spell":"stabilize"}]}],"spelldomains":"Persistence inquisition","strength":12,"dexterity":18,"constitution":14,"intelligence":12,"wisdom":24,"charisma":13,"baseatk":9,"cmb":10,"cmd":27,"feats":[{"feat":"Combat Casting"},{"feat":"Coordinated Defense*"},{"feat":"Deadly Aim"},{"feat":"Improved Critical (repeating heavy crossbow)"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Shake It Off*"},{"feat":"Shielded Caster*"},{"feat":"Step Up"},{"feat":"Swap Places*"},{"feat":"Toughness"},{"feat":"Weapon Focus (repeating heavy crossbow)"}],"skills":[{"skill":"Bluff","value":17},{"skill":"Diplomacy","value":17},{"skill":"Intimidate","value":22},{"skill":"Knowledge (nobility)","value":10},{"skill":"Knowledge (planes)","value":10},{"skill":"Knowledge (religion)","value":10},{"skill":"Perception","value":24},{"skill":"Profession (sailor)","value":26},{"skill":"Sense Motive","value":29},{"skill":"Spellcraft","value":15},{"skill":"Stealth","value":17},{"skill":"Survival","value":14},{"skill":"Swim","value":16}],"languages":["Common","Infernal"],"sq":["cunning initiative","inner strength","judgment (2, 5/day)","monster lore +7","relentless footing (10/day)","solo tactics","stern gaze","track +6"],"gear":"+1 mithral light fortification breastplate, crossbow of retribution (+1 Human bane seeking repeating heavy crossbow) with 10 bolts, +1 heavy mace, belt of physical might +4 (Con, Dex), brooch of shielding, headband of inspired wisdom +4, ring of force shield, robe of powerlessness, signet ring (worth 100 gp), silver unholy symbol of Asmodeus, spell component pouch, spyglass, potions of bull's strength (2), potions of invisibility (2), wand of cure critical wounds (20 charges)","before_combat":"Druvalia casts greater magic weapon on her crossbow every day. Once it's clear that her flagship is going to be attacked, she casts freedom of movement, heroism, ward the faithful (which affects her allies as well), defile armor, and invisibility purge. She also drinks a potion of bull's strength and casts weapon of awe on her crossbow.","during_combat":"At the beginning of combat, Druvalia casts divine power and flames of the faithful on her crossbow, and activates her judgment ability, typically making destruction and justice judgments, switching to other judgments as needed to counter the tactics of her opponents. While her allies engage foes in melee combat, Druvalia attacks with her crossbow, using her Deadly Aim and Rapid Shot feats. She alternates these attacks with spells such as flame strike, rebuke, or blistering invective. If her opponents are able to hit her with their attacks, Druvalia casts unwilling shield on an enemy combatant. All crew members aboard the Abrogail's Fury carry a case of five bolts for Druvalia's crossbow, and are trained to reload her crossbow whenever they are adjacent and she calls for ammunition, to save her the time of reloading it herself.","morale":"If reduced to fewer than 30 hit points, Druvalia dismisses her invisibility purge and drinks a potion of invisibility, retreating to the poop deck of the Abrogail's Fury or her cabin belowdecks to use her wand to heal herself before re-entering the fray. Druvalia has wagered everything on victory and fights to the death rather than surrender to pirates, knowing her soul is lost to Geryon whatever happens.","source":"AP 60, Pathfinder RPG Advanced Player's Guide 38"},{"name":"Kerdak Bonefist","cr":18,"xp":153600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":8},{"class":"Inner Sea Pirate","level":10}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":8,"ac":34,"ac_touch":23,"ac_flat_footed":26,"ac_mods":"+6 armor, +5 deflection, +8 Dex, +5 natural","hp":204,"hd":"8d10+10d8+116","hd_value":18,"fort":21,"ref":22,"will":14,"save_mods":"+2 vs. fear","defensive_abilities":["bravery +2","evasion","freedom of movement"],"speed":[{"type":"fly","speed":60,"maneuverability":"perfect"},{"type":"land","speed":30}],"melee":"+3 rapier +29 (1d6+5/18-20)","ranged":"enervating pistol +31 (1d8+6 plus 1d6 negative energy/19-20/4)","space":"5 ft.","reach":"5 ft. (15 ft. with pistol)","special_attacks":[{"type":"sneak attack","details":"+4d6"},{"type":"weapon training","details":"firearms +1"}],"spell_like_abilities_caster_level":18,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"vampiric touch"}]}],"strength":14,"dexterity":26,"constitution":20,"intelligence":14,"wisdom":14,"charisma":14,"baseatk":15,"cmb":17,"cmd":40,"cmd_special":"44 vs. disarm and sunder","feats":[{"feat":"Combat Reflexes"},{"feat":"Deadly Aim"},{"feat":"Exotic Weapon Proficiency (firearms)"},{"feat":"Greater Weapon Focus (pistol)"},{"feat":"Improved Critical (pistol)"},{"feat":"Improved Snap Shot*"},{"feat":"Point- Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Reload"},{"feat":"Rapid Shot"},{"feat":"Snap Shot*"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (pistol)"},{"feat":"Weapon Specialization (pistol)"}],"skills":[{"skill":"Acrobatics","value":28},{"skill":"Appraise","value":12},{"skill":"Bluff","value":12},{"skill":"Climb","value":17},{"skill":"Fly","value":18},{"skill":"Intimidate","value":25},{"skill":"Knowledge (local)","value":22},{"skill":"Perception","value":19},{"skill":"Profession (sailor)","value":30},{"skill":"Survival","value":17,"special":"+5 to determine direction or predict weather at sea"},{"skill":"Swim","value":17}],"languages":["Common","Polyglot"],"sq":["armor training 2","pirate tricks (burst of speed, classic duelist, drink for free, fearsome advance, shipboard authority, storm sailor)"],"special_abilities":[{"type":"Aging Effects","kind":"Ex","details":"Although Kerdak Bonefist is of old age, he has imbibed 2 doses of sun orchid elixir (The Inner Sea World Guide 301). As a result, he suffers none of the penalties while retaining the bonuses of his advanced age."},{"type":"Exceptional Resources","kind":"Ex","details":"As Hurricane King of the Shackles, Kerdak Bonefist has the wealth of a PC rather than an NPC, and his ability scores use a 20-point build. These advantages increase his CR by 1."},{"type":"Pirate Tricks","kind":"Ex","details":"With a DC 20 Profession (sailor) check once per day, Bonefist can double his ship's base movement for 1 round. He gains a +1 competence bonus on attack rolls with a cutlass, rapier, or short sword. He can drink for free and gains a +2 circumstance bonus on Diplomacy and Intimidate checks in any of his 10 \"favored taverns.\" If he deals damage with his sneak attack, Bonefist can make an Intimidate check as an immediate action to demoralize the damaged opponent. As a full-round action once per day, Bonefist can shout orders to his crew; any allies within 30 ft. who can hear him gain a +1 morale bonus on attack rolls or on a particular skill check for 10 rounds. Bonefist treats all storms as if they were one category less severe for the purposes of sailing and navigation. He can make an Acrobatics check to move his normal speed across uneven ground, and doesn't take a penalty on any Acrobatics checks due to slightly slippery, slightly unsteady, or moderately unsteady conditions."}],"gear":"+4 moderate fortification leather armor, enervating pistol (+1 reliable distance pistol) with 50 dry load* paper alchemical cartridges (bullet), +3 rapier, amulet of proof against detection and location, belt of physical might +6 (Dex, Con), boots of speed, coat of resistance +5 (as cloak of resistance), gloves of dueling*, handy haversack, headband of inspired wisdom +2, Hurricane Crown, ring of evasion, ring of freedom of movement, sniper goggles*, gunsmith's kit, tankard, 155 gp, dust of disappearance (2 uses), feather tokens (anchor, fan, and swan boat), potions of barkskin +5 (2), potions of cure serious wounds (2), potion of lesser restoration, potion of neutralize poison, potion of remove curse, potion of remove disease, potions of shield of faith +5 (2), entangling shot alchemical cartridges (10)","before_combat":"When opponents board the Filthy Lucre, Bonefist drinks potions of barkskin and shield of faith. In addition, his stat block includes the bonuses from the lord's banner of victory flying from the mainmast. Before stepping on deck, he uses the Hurricane Crown to cast winds of vengeance.","during_combat":"Bonefist dusts himself with dust of disappearance and activates his boots of speed, using his sniper goggles to make sneak attacks at range with his pistol. Whenever possible, he makes full attacks, using his Rapid Shot and Deadly Aim feats. He uses his invisibility and flight to stay out of reach of melee combatants, and his Snap Shot feats to make attacks of opportunity with his pistol. If possible, Bonefist tries to remain within 40 ft. of enemies to take advantage of his pistol's touch attack. In melee combat, Bonefist uses his vampiric touch ability and rapier, but retreats again to range as soon as possible.","morale":"If reduced to 50 hit points or fewer, Bonefist flees belowdecks to heal himself and ambush pursuers. Arrogant and stubborn to the last, Bonefist refuses to abandon his ship and fights to the death to keep his crown.","source":"AP 60, Pathfinder Player Companion: Pirates of the Inner Sea 24"},{"name":"Tsadok Goldtooth","cr":14,"xp":38400,"race":"half-Orc","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":15,"archetype":"scarred rager"}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human","Orc"],"init":3,"senses":["darkvision 60 ft."],"ac":19,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+8 armor, +3 Dex, -2 rage","hp":193,"hd":"15d12+90","hd_value":15,"fort":17,"ref":11,"will":11,"save_mods":"+4 vs. enchantment when raging, +5 vs. spells, spell-like abilities, and supernatural abilities","defensive_abilities":["improved tolerance","indomitable will","Orc ferocity","scarification* +5"],"dr":"4/-","speed":[{"type":"land","speed":20}],"melee":"+1 furious falchion +26 (2d4+15/15-20)","ranged":"doubleshot pepperbox +15 (2d8+2/4) or doubleshot pepperbox +19 (1d8+1/4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"greater rage","details":"34 rounds/day"},{"type":"rage powers","details":"auspicious mark, eater of magic, guarded stance [+3 dodge vs. melee], come and get me*, superstition +5, surprise accuracy +4, unexpected strike"}],"strength":26,"dexterity":17,"constitution":20,"intelligence":12,"wisdom":10,"charisma":8,"baseatk":15,"cmb":23,"cmb_special":"+25 sunder","cmd":34,"cmd_special":"36 vs. sunder","feats":[{"feat":"Blinding Critical"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Exotic Weapon Proficiency (firearms)"},{"feat":"Improved Critical (falchion)"},{"feat":"Improved Sunder"},{"feat":"Power Attack"},{"feat":"Quick Draw"}],"skills":[{"skill":"Acrobatics","value":18,"special":"-4 when jumping"},{"skill":"Climb","value":12},{"skill":"Craft (firearms)","value":5},{"skill":"Intimidate","value":19,"special":"+7 vs. non-barbarian humanoids"},{"skill":"Perception","value":18},{"skill":"Profession (sailor)","value":15},{"skill":"Survival","value":9},{"skill":"Swim","value":12}],"languages":["Common","Orc","Polyglot"],"sq":["Orc blood","terrifying visage","weapon familiarity"],"gear":"+2 breastplate, doubleshot pepperbox (+1 thundering pepperbox) with 20 bullets, +1 furious falchion, belt of physical might +2 (Str, Dex), cloak of resistance +3, dry load powder horn* with 20 doses of black powder, gunsmith's kit, keys to areas K1 and K3, 26 pp, 45 gp, potion of blur, potion of cure moderate wounds, adamantine bullets (6)","before_combat":"Tsadok drinks his potion of blur before entering combat.","during_combat":"Tsadok opens fire on the first round of combat with his doubleshot pepperbox, making a full attack by firing two barrels at a time at the most heavily armored opponent. When his pistol is empty, Tsadok drops the pepperbox, draws his falchion, and rages. The stat block above includes the extra bonuses from his furious falchion. Tsadok waits for opponents to come to him, using his unexpected strike rage power to make attacks of opportunity against foes who engage him. He activates his guarded stance rage power and makes Power Attacks, using his auspicious mark rage power to turn a miss into a hit if necessary, and attempts to sunder the weapons of anyone attacking him in melee.","morale":"Tsadok doesn't fear death and fights to the end.","base_statistics":"When not raging, Tsadok's statistics are AC 21, touch 13, flat-footed 18; hp 148; Fort +14, Will +8; Melee +1 furious falchion +21/+16/+11 (2d4+8/15-20); Str 20, Con 14; CMB +20 (+22 sunder), CMD 33 (35 vs. sunder); Skills Climb +9, Swim +9.","source":"AP 60, Ultimate Combat 29"},{"name":"Valeria Asperixus","cr":11,"xp":12800,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":6,"archetype":"polearm master"},{"class":"Hellknight","level":6}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"senses":["low-light vision"],"ac":26,"ac_touch":16,"ac_flat_footed":23,"ac_mods":"+10 armor, +3 deflection, +3 Dex","hp":121,"hd":"6d10+6d10+54","hd_value":12,"fort":14,"ref":10,"will":9,"save_mods":"+4 vs. compulsions, +2 vs. fear","defensive_abilities":["force of will (+2 vs. compulsion, vs. +4 phantasm)"],"speed":[{"type":"land","speed":30}],"melee":"+1 axiomatic bardiche* +19 (1d10+10/19-20)","ranged":"mwk composite longbow +16 (1d8+4/3)","space":"5 ft.","reach":"5 ft. (10 ft. with bardiche)","special_attacks":[{"type":"pole fighting"},{"type":"polearm training +1"},{"type":"smite chaos","details":"2/day, +2 attack and AC, +6 damage"},{"type":"steadfast pike"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect chaos"}]},{"frequency":"5/day","spells":[{"spell":"discern lies"}]}],"strength":19,"dexterity":16,"constitution":16,"intelligence":8,"wisdom":10,"charisma":14,"baseatk":12,"cmb":16,"cmd":32,"cmd_special":"34 vs. sunder","feats":[{"feat":"Bodyguard*"},{"feat":"Combat Reflexes"},{"feat":"Improved Vital Strike"},{"feat":"In Harm's Way*"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Stand Still"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bardiche*)"},{"feat":"Weapon Specialization (bardiche*)"}],"skills":[{"skill":"Handle Animal","value":6},{"skill":"Intimidate","value":15},{"skill":"Knowledge (engineering)","value":4},{"skill":"Knowledge (planes)","value":2},{"skill":"Perception","value":9},{"skill":"Ride","value":4},{"skill":"Swim","value":5}],"languages":["Common"],"sq":["disciplines (tracker 2/day, vigilance 2/day)","Hellknight armor 2","Order of the Scourge"],"special_abilities":[{"type":"Detect Chaos","kind":"Sp","details":"This ability functions like a paladin's detect evil ability, save that it detects chaos."},{"type":"Disciplines","kind":"Sp and Su","details":"Valeria has access to the Hellknight disciplines of tracker and vigilance. Twice per day, she can summon an eagle, riding dog, wolf, or leopard as if using a summon monster spell, but the duration is 1 hour. In addition, Valeria gains low-light vision, and as a full-round action twice per day, she can see through up to 5 ft. of wood or stone for as long as she concentrates (maximum 6 rounds). Metal or denser barriers block this effect."},{"type":"Force of Will","kind":"Ex","details":"Valeria gains a +4 bonus on Will saves against spells with the compulsion descriptor and a +2 bonus on Will saves against spells with the fear descriptor."},{"type":"Hellknight Armor","kind":"Ex","details":"Valeria has earned the right to wear a special type of masterwork full plate called Hellknight plate armor (Inner Sea World Guide 290). While wearing Hellknight plate, Valeria reduces the armor check penalty by 2, increases the maximum Dexterity bonus allowed by 1, and moves at full speed. Order Valeria is a member of the Order of the Scourge."},{"type":"Smite Chaos","kind":"Su","details":"This ability functions as the paladin's smite evil ability, but against chaotic-aligned creatures. This ability is twice as effective against outsiders with the chaotic subtype, chaotic-aligned aberrations, and fey."}],"gear":"+1 Hellknight plate, +1 axiomatic bardiche, masterwork composite longbow (+4 Str) with 20 arrows, belt of giant strength +2, elixir of swimming, potion of cat's grace, potion of cure serious wounds, potion of fly","before_combat":"Once the Abrogail's Fury comes under attack, Valeria drinks her potion of cat's grace and uses her tracker discipline to summon a leopard to help defend Admiral Druvalia Thrune. The effects of Druvalia's ward the faithful spell are already included in Valeria's stat block.","during_combat":"Valeria stays close to her mistress, Druvalia Thrune, throughout any combat, using her Bodyguard and In Harm's Way feats to intercept attacks meant for the admiral. If forcibly separated from her charge, she does everything in her power to get back to Druvalia's side. Valeria uses the reach of her bardiche to keep foes at a distance while the Chelish marines deal with them. She casts detect chaos as a move action to determine if any enemies are chaotic, then focuses her attacks on those foes, using her smite chaos ability and Improved Vital Strike with her axiomatic bardiche, using her pole fighting ability, if necessary, to shorten her grip on her weapon to attack adjacent foes. If knocked overboard, Valeria drinks her potion of fly to return to Druvalia's side.","morale":"Valeria is enraged if Druvalia is killed, and fights to the death to avenge her.","source":"AP 60, Advanced Player's Guide 106, Inner Sea World Guide 278"},{"name":"Urtleytlar, The Tempest Queen","cr":20,"xp":307200,"race":"scylla","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of Rovagug","level":8}],"alignment":"CE","size":"Huge","type":"aberration","sub_types":["aquatic"],"init":14,"senses":["all-around vision","blindsight 30 ft.","darkvision 60 ft.","low-light vision","see invisibility"],"auras":["frightful presence (30 ft., DC 27)"],"ac":38,"ac_touch":28,"ac_flat_footed":23,"ac_mods":"+5 deflection, +14 Dex, +1 dodge, +10 natural, -2 size","hp":406,"hd":"20d8+8d8+280","hd_value":28,"hp_mods":"fast healing 10","fort":22,"ref":22,"will":27,"defensive_abilities":["freedom of movement","improved evasion"],"dr":"10/cold iron and lawful","immunities":["charm effects","cold","confusion and insanity effects"],"resists":["acid 20","fire 20"],"sr":31,"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":30},{"type":"swim","speed":50}],"melee":"3 bites +37 (1d8+12/19-20 plus bleed), 4 tentacles +35 (1d6+6 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"bleed","details":"1d6"},{"type":"channel negative energy","details":"10/day, DC 21, 4d6"},{"type":"constrict","details":"1d6+10"},{"type":"deadly weather","details":"8 rounds/day"},{"type":"gale aura","details":"8 rounds/day"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"fly"},{"spell":"freedom of movement"},{"spell":"nondetection"},{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"acid arrow"},{"spell":"control water"},{"spell":"fog cloud"},{"spell":"greater dispel magic"},{"spell":"major image"}]},{"frequency":"1/day","spells":[{"spell":"control weather"},{"spell":"power word stun"},{"spell":"project image"},{"spell":"summon","details":"1 charybdis 100%, level 8"}]},{"frequency":"3/day","spells":[{"spell":"black tentacles"},{"spell":"charm monster"},{"spell":"insanity"},{"spell":"mirage arcana"},{"spell":"solid fog"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":8,"spellsprepared_concentration":17,"spellsprepared":[{"spell_level":4,"spell_slots":5,"spells":[{"spell":"cure critical wounds"},{"spell":"divine power"},{"spell":"inflict critical woundsB"},{"spell":"tongues"},{"spell":"unholy blight"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"call lightningB"},{"spell":"cure serious wounds","count":2},{"spell":"invisibility purge"},{"spell":"magic circle against good"},{"spell":"water breathing"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"darkness"},{"spell":"death knell"},{"spell":"gust of windB"},{"spell":"shatter","count":2},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"cause fear"},{"spell":"command","count":2},{"spell":"divine favor"},{"spell":"entropic shield"},{"spell":"obscuring mistB"},{"spell":"shield of faith"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"virtue"}]}],"spelldomains":"Destruction, Weather","strength":35,"dexterity":38,"constitution":31,"intelligence":18,"wisdom":29,"charisma":24,"baseatk":21,"cmb":35,"cmb_special":"+39 grapple","cmd":65,"feats":[{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Critical (bite)"},{"feat":"Mobility"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Selective Channeling"},{"feat":"Staggering Critical"},{"feat":"Stunning Critical"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Acrobatics","value":35},{"skill":"Bluff","value":25},{"skill":"Fly","value":35},{"skill":"Knowledge (nature)","value":22},{"skill":"Knowledge (planes)","value":25},{"skill":"Perception","value":34},{"skill":"Sense Motive","value":30},{"skill":"Spellcraft","value":31},{"skill":"Stealth","value":27},{"skill":"Swim","value":45},{"skill":"Use Magic Device","value":29}],"languages":["Common","Aboleth","Abyssal","Aklo","Aquan"],"sq":["amphibious","aura","change shape (1 humanoid form; alter self )","undersized weapons"],"gear":"amulet of mighty fists +3, belt of physical perfection +4, ring of protection +5","source":"AP 60, Pathfinder RPG Bestiary 2 241"},{"name":"Andel Gesseran","cr":3,"xp":800,"race":"human","age_category":"Adult","classes":[{"class":"expert","level":5}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+4 armor, +1 Dex","hp":27,"hd":"5d8+5","hd_value":5,"fort":2,"ref":5,"will":5,"speed":[{"type":"land","speed":30}],"melee":"quarterstaff +3 (1d6) or mwk dagger +3 (1d4/19-20)","ranged":"mwk dagger +5 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":12,"constitution":11,"intelligence":14,"wisdom":10,"charisma":9,"baseatk":3,"cmb":3,"cmd":14,"feats":[{"feat":"Lightning Reflexes"},{"feat":"Point-Blank Shot"},{"feat":"Scholar*"},{"feat":"Skill Focus (Knowledge *)","type":"history"}],"skills":[{"skill":"Acrobatics","value":3},{"skill":"Knowledge (arcana)","value":12},{"skill":"Knowledge (dungeoneering)","value":11},{"skill":"Knowledge (engineering)","value":9},{"skill":"Knowledge (history)","value":13},{"skill":"Knowledge (local)","value":9},{"skill":"Knowledge (nature)","value":9},{"skill":"Knowledge (religion)","value":9},{"skill":"Linguistics","value":8},{"skill":"Perception","value":3},{"skill":"Profession (scribe)","value":8}],"languages":["Common","Draconic","Dwarven","Elven","Giant","Thassilonian"],"gear":"chain shirt, masterwork dagger, quarterstaff, cloak of resistance +1, universal solvent, wayfinder, antitoxin (2), backpack, everburning torch, ink, inkpen, journal, rations (5 days), waterskin, 43 gp, acid flask, alchemist's fire, potions of cure light wounds (2), potion of protection from evil","source":"Shattered Star Player's Guide"},{"name":"Plutivarch Dremis","cr":2,"xp":600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"sorcerer","level":3}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+4 armor, +2 Dex, +1 dodge","hp":16,"hd":"3d6+3","hd_value":3,"fort":2,"ref":3,"will":2,"save_mods":"+2 vs. sleep and charm","speed":[{"type":"land","speed":30}],"melee":"mwk dagger +2 (1d4/19-20)","ranged":"dart +3 (1d4)","space":"5 ft.","reach":"5 ft.","spellsknown_caster":"sorcerer","spellsknown_caster_level":3,"spellsknown_concentration":6,"spellsknown":[{"spell_level":1,"spell_slots":6,"spells":[{"spell":"color spray"},{"spell":"identify"},{"spell":"mage armor"},{"spell":"magic missile"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"dancing lights"},{"spell":"daze"},{"spell":"read magic"},{"spell":"resistance"}]}],"bloodline":"arcane","strength":10,"dexterity":15,"constitution":12,"intelligence":13,"wisdom":8,"charisma":16,"baseatk":1,"cmb":1,"cmd":14,"feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Eschew Materials"}],"skills":[{"skill":"Bluff","value":9},{"skill":"Diplomacy","value":6},{"skill":"Perception","value":2},{"skill":"Sense Motive","value":5},{"skill":"Spellcraft","value":7},{"skill":"Stealth","value":5}],"languages":["Common","Varisian"],"sq":["arcane bond (dagger)","metamagic adept"],"gear":"masterwork dagger, darts (6), pouch with 35 gp and an amethyst worth 250 gp, potions of cure light wounds (2), potion of cure moderate wounds, potions of invisibility (2)","before_combat":"Plutivarch casts mage armor when he arrives at the tavern an hour before midnight. While he lies in wait, he listens carefully-if he hears the PCs approach, he drinks a potion of invisibility.","during_combat":"Plutivarch waits for the PCs to be clumped together so he can spring up and cast color spray on them, trying to catch as many as possible. He saves magic missile for foes that seem particularly resistant to his color spray tactic, and drinks a healing potion whenever he's below 10 hit points.","morale":"Plutivarch surrenders if brought below 4 hit points, dropping to his knees and begging for his life.","source":"AP 61"},{"name":"Fenster The Blight","cr":2,"xp":600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":2,"archetype":"unarmed fighter"},{"class":"rogue","level":1}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":14,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 dodge, +1 natural","hp":22,"hd":"2d10+1d8+3","hd_value":3,"fort":6,"ref":4,"will":-3,"defensive_abilities":["harsh training*"],"speed":[{"type":"land","speed":30}],"melee":"unarmed strike +5 (1d3+3)","ranged":"broken dagger +2 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"disease carrier"},{"type":"sneak attack","details":"+1d6"}],"strength":16,"dexterity":15,"constitution":13,"intelligence":10,"wisdom":5,"charisma":6,"baseatk":2,"cmb":5,"cmb_special":"+7 grapple","cmd":18,"cmd_special":"20 vs. grapple","feats":[{"feat":"Dodge"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Grapple"},{"feat":"Improved Unarmed Strike","type":"bonus"},{"feat":"Tiger Style*"}],"skills":[{"skill":"Acrobatics","value":8},{"skill":"Climb","value":8},{"skill":"Disable Device","value":8},{"skill":"Perception","value":3},{"skill":"Stealth","value":8},{"skill":"Survival","value":3}],"languages":["Common"],"sq":["trapfinding +1"],"special_abilities":[{"type":"Disease Carrier","kind":"Ex","details":"Fenster is swimming in disease. If he critically hits a creature with his unarmed strike, or if he grapples or is grappled by a creature, that creature is exposed to a random disease, as determined by a d4 roll: 1-filth fever; 2-leprosy; 3-red ache; 4-shakes. See page 557 of the Pathfinder RPG Core Rulebook for details on each disease."}],"gear":"rusty broken dagger, amulet of natural armor +1","during_combat":"If Fenster sees the PCs attempt to open his chest, or if they enter his home, he shrieks and charges in to attack, hoping to get in a sneak attack on a surprise round if possible. If he can't reach a foe via a charge, he throws his dagger on the first round. He focuses his attacks on unarmored foes if possible.","morale":"If reduced to 6 or fewer hit points, Fenster drops sobbing to his knees and begs for his miserable life.","source":"AP 61, Pathfinder RPG Ultimate Combat 48"},{"name":"Terisha Skiloni","cr":2,"xp":600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":3,"archetype":"acrobat"}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":7,"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+4 armor, +3 Dex","hp":26,"hd":"3d8+9","hd_value":3,"fort":3,"ref":6,"will":2,"defensive_abilities":["evasion"],"speed":[{"type":"land","speed":30}],"melee":"mwk whip +4 (1d3+1 nonlethal), mwk short sword +4 (1d6+1/19-20)","ranged":"mwk hand crossbow +6 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":12,"dexterity":17,"constitution":14,"intelligence":10,"wisdom":13,"charisma":8,"baseatk":2,"cmb":3,"cmd":16,"feats":[{"feat":"Exotic Weapon Proficiency (whip)"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Climb)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Bluff","value":5},{"skill":"Climb","value":12},{"skill":"Disguise","value":5},{"skill":"Escape Artist","value":8},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":7},{"skill":"Sleight of Hand","value":9},{"skill":"Stealth","value":9}],"languages":["Common","Varisian"],"sq":["expert acrobat","rogue talents (finesse rogue)","second chance 1/day"],"gear":"masterwork chain shirt, masterwork hand crossbow with 10 bolts, masterwork short sword, masterwork whip, climber's kit, grappling hook with 50-foot silk rope, second story harness, silver holy symbol, thieves' tools, 4 pp, 47 gp, potions of cure light wounds (3), potions of lesser restoration (2), smokestick, tanglefoot bags (2)","during_combat":"Terisha opens combat with her hand crossbow if she can get a sneak attack with it; otherwise, she uses Acrobatics to stay mobile and flank foes with her thugs.","morale":"Terisha flees combat if reduced to fewer than 10 hit points-she doesn't flee to the Crow piling until she's sure that she's not being followed. If cornered, she surrenders.","source":"AP 61, Pathfinder RPG Advanced Player's Guide 132"},{"name":"Varisian Thug","cr":0.5,"xp":200,"race":"human","age_category":"Adult","classes":[{"class":"warrior","level":2}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"ac":17,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+6 armor, +1 shield","hp":18,"hd":"2d10+7","hd_value":2,"fort":4,"ref":0,"will":0,"speed":[{"type":"land","speed":20}],"melee":"morningstar +5 (1d8+2)","ranged":"light crossbow +2 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":11,"constitution":12,"intelligence":9,"wisdom":10,"charisma":8,"baseatk":2,"cmb":4,"cmd":14,"feats":[{"feat":"Toughness"},{"feat":"Weapon Focus (morningstar)"}],"skills":[{"skill":"Intimidate","value":4},{"skill":"Ride","value":-1}],"languages":["Common"],"gear":"chainmail, light wooden shield, light crossbow with 20 bolts, morningstar, 12 gp","during_combat":"These thugs spread out in combat, each attacking different foes. They prefer to fight in melee.","morale":"The thugs surrender if reduced to fewer than 5 hit points. If Terisha is defeated or flees, the thugs attempt to flee as well.","source":"AP 61"},{"name":"Tower Girl","cr":0.5,"xp":200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":1,"archetype":"acrobat"}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 armor, +3 Dex","hp":11,"hd":"1d8+3","hd_value":1,"fort":2,"ref":5,"will":1,"speed":[{"type":"land","speed":30}],"melee":"short sword +1 (1d6+1/19-20)","ranged":"hand crossbow +3 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":12,"dexterity":17,"constitution":14,"intelligence":10,"wisdom":13,"charisma":8,"baseatk":0,"cmb":3,"cmd":14,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Skill Focus (Climb)"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Bluff","value":3},{"skill":"Climb","value":10},{"skill":"Disable Device","value":6},{"skill":"Escape Artist","value":6},{"skill":"Knowledge (local)","value":4},{"skill":"Perception","value":5},{"skill":"Sleight of Hand","value":7},{"skill":"Stealth","value":7}],"languages":["Common","Varisian"],"sq":["expert acrobat"],"gear":"studded leather, hand crossbow with 10 bolts, short sword, climber's kit, grappling hook with 50-foot silk rope, hooded lantern, oil, second-story harness, thieves' tools, 15 gp, smokestick, tanglefoot bags (2)","during_combat":"A Tower Girl uses Acrobatics to stay mobile in a fight, repositioning as needed to provide her allies flanking opportunities.","morale":"A Tower Girl flees deeper into the Crow to warn her sisters and join larger groups in defending the Crow if brought below 4 hit points unless otherwise noted in the text.","source":"AP 61, Advanced Player's Guide 132"},{"name":"Ayala Javeski","cr":3,"xp":800,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":1},{"class":"rogue","level":2,"archetype":"acrobat"}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human","shapechanger"],"templates_applied":"natural wererat","init":8,"senses":["low-light vision","scent"],"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+3 armor, +4 Dex, +1 dodge, +2 natural","hp":27,"hd":"1d10+2d8+8","hd_value":3,"fort":4,"ref":7,"will":2,"defensive_abilities":["evasion"],"dr":"10/silver","speed":[{"type":"land","speed":30}],"melee":"+1 bladed scarf +8 (1d6+2)","ranged":"mwk composite shortbow +7 (1d6+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":12,"dexterity":19,"constitution":15,"intelligence":10,"wisdom":15,"charisma":11,"baseatk":2,"cmb":3,"cmd":18,"feats":[{"feat":"Dodge"},{"feat":"Exotic Weapon Proficiency (bladed scarf)"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (bladed scarf)"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":9},{"skill":"Disable Device","value":12},{"skill":"Intimidate","value":6},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":8},{"skill":"Stealth","value":10}],"languages":["Common","Varisian"],"sq":["change shape (Human, hybrid, and dire rat; polymorph)","expert acrobat","lycanthropic empathy","rogue talents (combat trick)"],"gear":"masterwork studded leather, +1 bladed scarf, masterwork composite shortbow with 20 arrows, climber's kit, grappling hook with 50-foot silk rope, masterwork thieves' tools, second-story harness, bloodroot (2), tanglefoot bags (3)","before_combat":"Ayala uses her 2 vials of bloodroot to poison her bladed scarf and one arrow.","during_combat":"Ayala starts combat by making a sneak attack with her bow if she wins initiative; otherwise, she works with her donkey rats to flank foes. If both donkey rats are slain, she retreats up into the Crow, using tanglefoot bags to slow pursuit. If she can't find other Tower Girls to aid her, she picks a hiding spot and waits to ambush the PCs, continuing this cat-and-mouse game as best she can while trusting her damage reduction to keep her from becoming too wounded.","morale":"If reduced below 5 hit points, Ayala flees to a safe hiding place, assumes dire rat form, and then flees back to Magnimar. She harbors a grudge-at this point, she'll swallow her pride and seek out new allies among another Sczarni gang. Eventually, she'll organize revenge against the PCs, perhaps ambushing them with a new gang of recently infected wererats at a later date.","source":"AP 61, Pathfinder RPG Bestiary 197, Pathfinder RPG Advanced Player's Guide 132"},{"name":"Abyssal Larva","cr":4,"xp":1200,"race":"Abyssal Larva","age_category":"Adult","alignment":"CE","size":"Large","type":"outsider","sub_types":["chaotic","evil","extraplanar"],"init":-1,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":8,"ac_flat_footed":17,"ac_mods":"-1 Dex, +9 natural, -1 size","hp":42,"hd":"5d10+15","hd_value":5,"fort":6,"ref":3,"will":1,"immunities":["mind-affecting effects"],"resists":["acid 5","cold 5","fire 5"],"speed":[{"type":"land","speed":20}],"melee":"bite +8 (1d6+6 plus 1d6 acid)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"maggot spray"}],"strength":18,"dexterity":8,"constitution":15,"intelligence":3,"wisdom":10,"charisma":7,"baseatk":5,"cmb":10,"cmd":19,"cmd_special":"can't be tripped","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Step Up"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":11},{"skill":"Swim","value":9}],"languages":["Abyssal"],"sq":["tortured mind"],"special_abilities":[{"type":"Maggot Spray","kind":"Ex","details":"Once per day, an abyssal larva can spew a stream of maggots at a single opponent within 20 feet. The larvae makes a +3 ranged touch attack-if it hits, the target is sickened for 1d4 rounds (Reflex DC 16 reduces the duration to 1 round). The save DC is Strength-based."},{"type":"Tortured Mind","kind":"Ex","details":"An abyssal larva's mind is pain and chaos. As a result, it is immune to mind-affecting effects. In addition, any creature that attempts to contact an abyssal larva with a mind-affecting effect or spell must succeed at a DC 18 Will save or be confused for 1 minute. The save DC is Constitution-based and includes a +4 racial bonus."}],"during_combat":"The larva is barely intelligent, but knows that foes with large weapons hurt more-it focuses its attacks on the target with the biggest weapon as a result. It pursues foes relentlessly, but can't open doors. It also doesn't differentiate between PCs and the other denizens of this dungeon, and can be used to attack other creatures if the PCs lure it along.","morale":"The larva fights to the death.","source":"AP 61, Tome of Horrors Complete 15"},{"name":"Nupperibo","cr":1,"xp":400,"race":"Nupperibo Devil","age_category":"Adult","alignment":"LE","size":"Medium","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":0,"senses":["blindsight 60 ft.","darkvision 60 ft."],"ac":12,"ac_touch":10,"ac_flat_footed":12,"ac_mods":"+2 natural","hp":5,"hd":"1d10","hd_value":1,"fort":2,"ref":2,"will":0,"dr":"5/good or silver","immunities":["fire","mind-affecting effects","poison"],"resists":["acid 10","cold 10"],"speed":[{"type":"land","speed":20}],"melee":"spear +1 (1d8/x3), 2 claws +1 (1d4)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":10,"constitution":10,"wisdom":11,"charisma":4,"baseatk":1,"cmb":1,"cmd":11,"sq":["infernal slave"],"special_abilities":[{"type":"Infernal Slave","kind":"Ex","details":"Nupperibos are devils, yet they are essentially mindless shells of solidified torment. Like golems, they have no real minds of their own, but rather follow orders and programming instilled within them by more powerful devils. In the case of multiple orders, only the orders of the most powerful devil are followed. They can utilize simple weapons if commanded, attacking with proficiency, and can also manipulate simple objects like doors. Armor, more complex weapons, and complex tools are beyond their ability to comprehend."}],"during_combat":"A nupperibo attacks the closest target. It reverts to attacking with its claws only if it is disarmed.","morale":"Nupperibos fight to the death.","source":"AP 61, Tome of Horrors Complete 200"},{"name":"Stink","cr":4,"xp":1200,"race":"lemure","age_category":"Adult","alignment":"LE","size":"Medium","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"templates_applied":"advanced","init":8,"senses":["darkvision 60 ft.","see in darkness"],"auras":["stench (10 ft., DC 16)"],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 Dex, +4 natural","hp":38,"hd":"4d10+16","hd_value":4,"fort":8,"ref":5,"will":7,"dr":"5/good or silver","immunities":["fire","poison"],"resists":["acid 10","cold 10"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +8 (1d6+4)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":18,"constitution":18,"intelligence":4,"wisdom":17,"charisma":7,"baseatk":4,"cmb":8,"cmd":22,"feats":[{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (claws)"}],"skills":[{"skill":"Escape Artist","value":11},{"skill":"Perception","value":10},{"skill":"Stealth","value":11}],"languages":["Infernal"],"during_combat":"Stink is a coward, and never begins combat. It prefers to whine and cry, even if attacked. That said, once it's reduced to fewer than 30 hit points, it suddenly flies into a furious rage-this replaces its cowardice and sends it into a rampage of unleashed anger. At this point, Stink attacks the nearest foe in sight. It reverts to its cowardly persona only once no obvious living targets remain.","morale":"Stink fights to the death.","source":"AP 61, Pathfinder RPG Bestiary 79, 294"},{"name":"Lockerbie Brast","cr":4,"xp":1200,"race":"lacedon","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":3}],"alignment":"NE","size":"Medium","type":"undead","init":7,"senses":["darkvision 60 ft."],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+4 armor, +3 Dex, +2 natural","hp":45,"hd":"5d8+23","hd_value":5,"fort":5,"ref":6,"will":7,"defensive_abilities":["channel resistance +2","evasion","trap sense +1"],"immunities":["undead traits"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"bite +6 (1d6+3 plus disease and paralysis), 2 claws +6 (1d4+3 plus paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"disease","details":"DC 15"},{"type":"paralysis","details":"DC 15"},{"type":"sneak attack","details":"+2d6"}],"strength":17,"dexterity":17,"intelligence":13,"wisdom":16,"charisma":18,"baseatk":3,"cmb":6,"cmd":19,"feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Improved Disarm"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Bluff","value":12},{"skill":"Craft (painting)","value":9},{"skill":"Intimidate","value":12},{"skill":"Knowledge (dungeoneering)","value":6},{"skill":"Perception","value":11},{"skill":"Stealth","value":11},{"skill":"Swim","value":19}],"languages":["Common","Necril"],"sq":["rogue talents (combat trick)","trapfinding +1"],"gear":"+1 studded leather, painting supplies in a water-tight case (the case itself is worth 100 gp, but the painting supplies are mundane), necklace of fireballs I","during_combat":"Lockerbie attacks the closest foe in the first round of combat, hoping to maximize his sneak attacks. Once the battle begins in earnest, he fights using Combat Expertise and disarms foes, dropping weapons into the water to give himself a greater advantage.","morale":"If reduced to fewer than 12 hit points, Lockerbie flees south to area D7, then east down the tunnel there, hoping to make it to Magnimar to escape into the slums to recover. He doesn't return to these sewers, nor does he seek revenge on the PCs.","source":"AP 61, Pathfinder RPG Bestiary 146"},{"name":"Cave Moray","cr":2,"xp":600,"race":"Cave Moray","age_category":"Adult","alignment":"N","size":"Medium","type":"magical beast","init":3,"senses":["darkvision 60 ft.","low-light vision","tremorsense 60 ft."],"ac":15,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+3 Dex, +2 natural","hp":19,"hd":"3d10+3","hd_value":3,"fort":4,"ref":6,"will":2,"speed":[{"type":"land","speed":20}],"melee":"bite +5 (2d6+3)","space":"5 ft.","reach":"10 ft.","special_attacks":[{"type":"ambush"},{"type":"recoil attack"}],"strength":14,"dexterity":17,"constitution":13,"intelligence":2,"wisdom":13,"charisma":10,"baseatk":3,"cmb":5,"cmd":18,"cmd_special":"can't be tripped","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Perception","value":8},{"skill":"Stealth","value":11,"special":"+4 in rocky or stony areas"}],"special_abilities":[{"type":"Ambush","kind":"Ex","details":"A cave moray gains a +4 circumstance bonus on attack rolls made during a surprise round."},{"type":"Recoil Attack","kind":"Ex","details":"When a cave moray attacks from a cyst, it gains the benefit of a charge attack even though it doesn't actually move. This lunging attack, combined with a second set of jaws that can extend further from its primary jaws, work to extend its reach to 15 feet."}],"during_combat":"The cave morays lunge out to attack anyone who passes within reach of their recoil attack.","morale":"The cave morays fight to the death.","source":"AP 61, Tome of Horrors Complete 99"},{"name":"Magister Khrysm","cr":6,"xp":2400,"race":"derro","gender":"Female","age_category":"Adult","classes":[{"class":"alchemist","level":4}],"alignment":"CE","size":"Small","type":"humanoid","sub_types":["derro"],"init":9,"senses":["darkvision 60 ft."],"ac":21,"ac_touch":17,"ac_flat_footed":15,"ac_mods":"+2 armor, +5 Dex, +1 dodge, +2 natural, +1 size","hp":70,"hd":"7d8+39","hd_value":7,"fort":9,"ref":10,"will":9,"save_mods":"+2 vs. poison","immunities":["confusion","insanity"],"sr":18,"weaknesses":["vulnerability to sunlight"],"speed":[{"type":"land","speed":30}],"melee":"mwk aklys +6 (1d6-1)","ranged":"mwk aklys +12 (1d6-1) or bomb +12 (2d6+4 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bomb","details":"8/day, 2d6+4 fire, DC 16"},{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"ghost sound"},{"spell":"levitate"}]},{"frequency":"1/day","spells":[{"spell":"daze"},{"spell":"deeper slumber"},{"spell":"modify memory"},{"spell":"sound burst"}]}],"extractsprepared_caster":"alchemist","extractsprepared_caster_level":4,"extractsprepared":[{"spell_level":2,"spells":[{"spell":"cure moderate wounds"},{"spell":"invisibility"}]},{"spell_level":1,"spells":[{"spell":"cure light wounds","count":2},{"spell":"disguise self"},{"spell":"shield"}]}],"strength":8,"dexterity":20,"constitution":18,"intelligence":18,"wisdom":5,"charisma":20,"baseatk":5,"cmb":3,"cmd":19,"feats":[{"feat":"Brew Potion"},{"feat":"Derro Magister"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Throw Anything"},{"feat":"Toughness"}],"skills":[{"skill":"Craft (alchemy)","value":14},{"skill":"Heal","value":11},{"skill":"Knowledge (arcana)","value":14},{"skill":"Knowledge (dungeoneering)","value":8},{"skill":"Knowledge (nature)","value":11},{"skill":"Perception","value":7},{"skill":"Spellcraft","value":14},{"skill":"Stealth","value":16}],"languages":["Common","Aklo","Dwarven","Necril","Terran","Undercommon"],"sq":["alchemy  (alchemy crafting +4, identify potions)","discoveries (acid bomb, precise bombs [4 squares])","madness","mutagen (+4/-2, +2 natural, 40 minutes)","poison use","swift alchemy"],"gear":"masterwork leather armor, masterwork aklys, headband of vast intelligence +2, key ring to doors in area D12, potions of cure moderate wounds (2), potions of invisibility (2), acid (4)","during_combat":"Khrysm throws a bomb (she prefers acid bombs) on the first round of combat if there are still flat-footed targets available. She drinks an extract of shield otherwise (or drinks the potion on the second round), and in the next round uses invisibility, then makes another sneak attack with a bomb the next round. She repeats this tactic until she runs out of invisibility extracts and potions, after which point she levitates up out of reach to throw her remaining bombs. She saves deeper slumber for use against foes that seem capable of reaching her in melee easily.","morale":"When reduced to fewer than 10 hit points, Khrysm uses sound burst to try to stun a few PCs and then flees toward the stairs in area D8 to retreat back down to Nar-Voth-if she escapes, she doesn't return anytime soon, but may gather more resources to seek revenge on the PCs at a later date.","source":"AP 61, Pathfinder RPG Bestiary 70, Pathfinder RPG Advanced Player's Guide 26"},{"name":"Advanced Shriezyx","cr":5,"xp":1600,"race":"shriezyx","age_category":"Adult","alignment":"CE","size":"Medium","type":"aberration","templates_applied":"advanced","init":9,"senses":["darkvision 60 ft.","tremorsense 60 ft."],"ac":21,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+5 Dex, +6 natural","hp":52,"hd":"7d8+21","hd_value":7,"fort":7,"ref":7,"will":8,"defensive_abilities":["ferocity"],"immunities":["mind-affecting effects"],"weaknesses":["fear of fire","vulnerable to fire"],"speed":[{"type":"climb","speed":30},{"type":"land","speed":30}],"melee":"bite +10 (1d6+3 plus poison), 4 claws +10 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"slowing toxin"},{"type":"web","details":"+10 ranged, DC 16, 7 hp"}],"strength":17,"dexterity":21,"constitution":16,"intelligence":7,"wisdom":16,"charisma":6,"baseatk":5,"cmb":8,"cmd":23,"cmd_special":"35 vs. trip","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Step Up"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":21},{"skill":"Perception","value":13}],"languages":["Thassilonian"],"special_abilities":[{"type":"Fear of Fire","kind":"Ex","details":"A shriezyx within 30 ft. of a fire the size of a torch or larger becomes shaken as long as it remains within that range. If damaged by fire, a shriezyx must make a successful Will save (DC equals the amount of fire damage dealt) or become frightened for 1 round."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 14; frequency 1/round for 6 rounds; effect 1d2 Str; cure 1 save."},{"type":"Slowing Toxin","kind":"Su","details":"A shriezyx's web is coated with a toxin that deadens the nerves on contact. Any creature struck by a shriezyx's web must succeed at a DC 14 Fortitude save or become slowed (as per the spell) for 1 minute. Each round, a victim may attempt a new DC 14 Fortitude save to end the effect early. This toxin fades quickly from spun webs-it can only affect targets on the round the web is spun. Existing webs, while they remain sticky and tangled, don't have this slowing effect. The save DC is Constitution-based."}],"during_combat":"The shriezyx work together, using their webs at first to slow down enemies and then ganging up to flank foes still able to reach them. Any creature that uses fire against them earns both monsters' wrath, and assuming they can avoid becoming frightened, they focus all their attacks on these foes to the exclusion of others.","morale":"The shriezyx fight to the death.","source":"AP 61, Pathfinder Campaign Setting: Magnimar, City of Monuments 60"}];
